export const difficultChoicesId = (number: StoryLessonNumber) => `conversational-skills-L5-C4-${number}-${difficultChoicesEpisodes[number].skill}-ja-v1`;

export function buildDifficultChoicesLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildNewBeginningLesson(number, previous, 'https://api.fluentxverse.com', reference, {
    episode: difficultChoicesEpisodes[number], id: difficultChoicesId(number), chapterName: 'Difficult Choices',
    setting: 'Eastbridge Creative, a fictional marketing agency in Tokyo. The hotel proposal investigation continues with information security specialist Ms. Sato and department director Kuroda.',
    previousSummary: index === 0 ? missingProposalEpisodes[9].closing : difficultChoicesEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(5)}\nUser reference: Difficult Choices. Preserve only these eight episodes, mapped to slots 1-4 and 6-9. Slots 5/10 are dynamic checkpoints. Standard guides, fixed feedback, Japanese support, basic pronunciation, short private listening and fresh visible reading challenges. No images, romance, required monologues or alternate-role disclaimers. Forecasts are estimates, not earned revenue. The increase is almost twenty percent, not exactly twenty. Kuroda's approval is present; the required review record is missing. Approval, authorship, actual account user and intent are separate. The removal-request document is not compliance approval. Mika did not delete records. The consultant domain belongs to a company Northstar acquired last year. Ethan's lack of knowledge is his statement, not independently established. The email provides a possible route, not proof of a deliberate leak or final responsibility. Do not confirm delivery to Northstar, invent a confession, decide guilt, promise the contract or resolve the next chapter.`,
  });
  lesson.storyData.storyTitle = 'Tokyo After Hours';
  lesson.storyData.characters = [
    { id: 'mika', name: 'Mika Tanaka', role: 'main', description: 'Marketing worker from Osaka. She questions conflicting instructions, preserves records and reports concerns carefully.' },
    { id: 'ethan', name: 'Ethan', role: 'supporting', description: 'Project manager from Bristol. He worries about the team and brings Kuroda’s email about an outside review. His responsibility remains open.' },
    { id: 'soo-jin', name: 'Soo-jin', role: 'supporting', description: 'Creative director from Seoul. She remembers an earlier concern, advises keeping facts and supports Mika.' },
    { id: 'daichi', name: 'Daichi', role: 'supporting', description: 'Senior analyst. He finds a higher forecast and a missing review record without treating them as proof of guilt.' },
    { id: 'sato', name: 'Ms. Sato', role: 'supporting', description: 'Information security specialist. She checks records and the consultant’s company connection; the account user is not yet known.' },
    { id: 'kuroda', name: 'Director Kuroda', role: 'supporting', description: 'Department director. His approval, removal request, account and email raise questions. Intent and possible deception are unresolved.' },
  ];
  lesson.learnData.steps[0].discussionPart.tutorSteps[2].tip = 'Use the supplied character details. Accept short answers and a simple reason.';
  lesson.stepBData.grammarTip.tutorSteps[1].tip = 'Use one simple example from the scene. Correct one important error if needed.';
  return { ...lesson, course: 'conversational-skills', level: 5, chapter: 4, lessonNumber: number, levelBadge: 'ELEMENTARY', chapterLabel: 'Chapter 4: Difficult Choices', status: previous.status || 'draft', overlayColor: '#17252bcc', supportLanguage: 'ja', authoringLanguageTarget: 'TOEIC 225-545', authoringLanguageRevision: 'toeic-v1' };
}

export function buildDifficultChoicesChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildDifficultChoicesLesson(number, {}, reference));
}
